.wp-home .newsletter-form {
    display: flex;
    max-width: 450px;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    overflow: hidden;
    background: #fff;
}
.wp-home .newsletter-form input[type="email"] {
    flex: 1;
    padding: 12px 15px;
    border: none;
    outline: none;
    font-size: 14px;
    color: #333;
}
.wp-home .newsletter-form input[type="email"]::placeholder {
    color: #999;
}
.wp-home .newsletter-form button {
    background: #DD2E44;
    color: #fff;
    border: none;
    padding: 12px 25px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.3s ease;
}
.wp-home .newsletter-form button:hover {
    background: #d43f4f;
}
.wp-home .newsletter-message {
    margin-top: 10px;
    font-size: 14px;
}
.wp-home .newsletter-message.success { color: green; }
.wp-home .newsletter-message.error { color: red; }
